commands.command:
Get-WmiObject Win32_Process | ForEach-Object {
  $owner = $_.GetOwner()
  [PSCustomObject]@{
    PID     = $_.ProcessId
    Name    = $_.Name
    Domain  = $owner.Domain
    User    = $owner.User
    CmdLine = $_.CommandLine
  }
} | Where-Object { $_.User } | Format-Table -AutoSize

Get-GPO -All | ForEach-Object {
  $gpo = $_
  [PSCustomObject]@{
    Name         = $gpo.DisplayName
    Id           = $gpo.Id
    DomainName   = $gpo.DomainName
    CreationTime = $gpo.CreationTime
    ModifiedTime = $gpo.ModificationTime
    GpoStatus    = $gpo.GpoStatus
  }
} | Sort-Object ModifiedTime -Descending | Format-Table -AutoSize

Get-Mailbox -ResultSize Unlimited | ForEach-Object {
  Get-InboxRule -Mailbox $_.PrimarySmtpAddress -EA SilentlyContinue | Where-Object { $_.ForwardTo -or $_.RedirectTo -or $_.ForwardAsAttachmentTo } | Select-Object @{N='Mailbox';E={$_.PrimarySmtpAddress}}, Name, ForwardTo, RedirectTo
} | Where-Object { $_ } | Format-Table -AutoSize

@($env:TEMP, $env:APPDATA, "$env:USERPROFILE\Downloads") | ForEach-Object {
  Get-ChildItem $_ -Recurse -ErrorAction SilentlyContinue | ForEach-Object {
    $streams = Get-Item $_.FullName -Stream * -ErrorAction SilentlyContinue | Where-Object { $_.Stream -ne ':$DATA' }
    if ($streams) { [PSCustomObject]@{ File=$_.FullName; Streams=$streams.Stream -join ', ' } }
  }
}

Get-ScheduledTask | ForEach-Object {
  $task = $_
  $task.Actions | Where-Object { $_.Execute -match '(?i)(Temp|AppData|Downloads|ProgramData|Users)' } | ForEach-Object {
    [PSCustomObject]@{ Task=$task.TaskName; Execute=$_.Execute; Args=$_.Arguments }
  }
} | Format-Table -AutoSize

Get-WmiObject Win32_Service | Where-Object { $_.PathName } | ForEach-Object {
  $path = $_.PathName -replace '"',''
  $path = $path.Split(' ')[0]
  $acl  = Get-Acl $path -EA SilentlyContinue
  $acl.Access | Where-Object { $_.IdentityReference -match 'Everyone|Users|Authenticated Users' -and $_.FileSystemRights -match 'Write|FullControl|Modify' } | ForEach-Object {
    [PSCustomObject]@{ Service=$_.ServiceName; Path=$path; Identity=$_.IdentityReference; Rights=$_.FileSystemRights }
  }
} | Format-Table -AutoSize

$amcache = 'C:\Windows\AppCompat\Programs\Amcache.hve'
if (Test-Path $amcache) {
  Write-Output '[*] AmCache found - use AmcacheParser.exe or similar tool for full analysis'
  Write-Output "[*] Location: $amcache"
  Write-Output "[*] Last Modified: $((Get-Item $amcache).LastWriteTime)"
}

Get-ChildItem 'C:\Users\*\AppData\Roaming\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt' -ErrorAction SilentlyContinue | ForEach-Object {
  Write-Output "=== $($_.FullName) ==="
  Get-Content $_ | Select-Object -Last 50
}

Get-ChildItem 'C:\Users\*\AppData\Roaming\Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt' -EA SilentlyContinue | ForEach-Object {
  $user = ($_.FullName -split '\\')[2]
  $hits = Get-Content $_ | Where-Object { $_ -match '(?i)(-enc|IEX|WebClient|TCPClient|mimikatz|Invoke-|secretsdump|BloodHound)' }
  if ($hits) { [PSCustomObject]@{ User=$user; Hits=$hits.Count; Commands=$hits -join ' | ' } }
} | Format-Table -AutoSize

Get-Process | ForEach-Object {
  $p = $_
  try {
    $p.Modules | Where-Object { $_.FileName -notmatch '(?i)(Windows|Program Files|Microsoft)' } | Select-Object @{N='PID';E={$p.Id}}, @{N='Process';E={$p.Name}}, FileName, ModuleName, FileVersion
  } catch {}
} | Format-Table -AutoSize

Get-ChildItem 'C:\Users' -Recurse -Include '*.ps1','*.psm1' -ErrorAction SilentlyContinue | ForEach-Object {
  $sig = Get-AuthenticodeSignature $_.FullName
  [PSCustomObject]@{ File=$_.FullName; Status=$sig.Status; Signer=$sig.SignerCertificate.Subject }
} | Where-Object { $_.Status -ne 'Valid' } | Format-Table -AutoSize

$env:PSModulePath -split ';' | ForEach-Object {
  [PSCustomObject]@{
    Path   = $_
    Exists = Test-Path $_
    Owner  = (Get-Acl $_ -EA SilentlyContinue).Owner
  }
} | Format-Table -AutoSize

$toolNames = @('mimikatz','mimi','lazagne','rubeus','SharpHound','bloodhound','chisel','ligolo','plink','nmap','masscan','procdump','pwdump','wce','fgdump','lsassy','nanodump')
foreach ($tool in $toolNames) {
  $found = Get-ChildItem C:\ -Recurse -Filter "*$tool*" -ErrorAction SilentlyContinue | Select-Object -First 3
  if ($found) { Write-Warning "[!] Found: $($found.FullName -join ', ')" }
}

# Task registered:
$reg = Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TaskScheduler/Operational'; Id=106} -MaxEvents 30 | Select TimeCreated,@{N='Detail';E={$_.Message}}
# Task deleted:
$del = Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TaskScheduler/Operational'; Id=141} -MaxEvents 30 | Select TimeCreated,@{N='Detail';E={$_.Message}}
# Task action launched:
$run = Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-TaskScheduler/Operational'; Id=200} -MaxEvents 30 | Select TimeCreated,@{N='Detail';E={$_.Message}}
$reg; $del; $run

# Reboots:
Get-WinEvent -FilterHashtable @{LogName='System'; Id=6005} -MaxEvents 10 | Select TimeCreated,@{N='Event';E={'System Boot'}}
Get-WinEvent -FilterHashtable @{LogName='System'; Id=6006} -MaxEvents 10 | Select TimeCreated,@{N='Event';E={'Clean Shutdown'}}
# Also use: (Get-Date) - (Get-CimInstance Win32_OperatingSystem).LastBootUpTime | Select -ExpandProperty TotalHours

# Run on DNS server or with admin rights
Get-DnsServerZone | Where-Object {
    -not $_.IsReverseLookupZone -and $_.ZoneType -eq 'Primary'
} | ForEach-Object {
    $zone = $_.ZoneName
    Get-DnsServerResourceRecord -ZoneName $zone | Where-Object { $_.HostName -eq '*' } | ForEach-Object {
        [PSCustomObject]@{
            Zone       = $zone
            RecordName = $_.HostName
            RecordType = $_.RecordType
            Data       = $_.RecordData.IPv4Address
        }
    }
}

Get-WinEvent -ComputerName $DC -FilterHashtable @{
    LogName      = 'Microsoft-Windows-DNSServer/Audit'
    Id           = 292
    StartTime    = (Get-Date).AddDays(-7)
} | Where-Object {
    $_.Message -match '\*'
} | Select-Object TimeCreated,
    @{N='Zone';E={$_.Properties[1].Value}},
    @{N='Record';E={$_.Properties[2].Value}},
    @{N='Owner';E={$_.Properties[6].Value}} | Format-Table -AutoSize

Get-WinEvent -ComputerName $DC -FilterHashtable @{
    LogName   = 'Security'
    Id        = 5137
    StartTime = (Get-Date).AddDays(-1)
} | Where-Object {
    $_.Message -match 'DomainDnsZones' -and $_.Message -match 'dnsNode'
} | Select-Object TimeCreated,
    @{N='Actor';E={$_.Properties[3].Value}},
    @{N='Object';E={$_.Properties[8].Value}} | Format-Table -AutoSize

Get-WinEvent -ComputerName $DC -FilterHashtable @{
    LogName   = 'Security'
    Id        = 5136
    StartTime = (Get-Date).AddHours(-24)
} | Where-Object {
    $_.Properties[8].Value -match 'DomainDnsZones'
} | Select-Object TimeCreated,
    @{N='Actor';E={$_.Properties[3].Value}},
    @{N='Object';E={$_.Properties[8].Value}},
    @{N='Attribute';E={$_.Properties[10].Value}} | Format-Table -AutoSize

Get-WinEvent -FilterHashtable @{
    LogName   = 'Microsoft-Windows-Sysmon/Operational'
    Id        = 3
    StartTime = (Get-Date).AddHours(-24)
} | Where-Object {
    $_.Message -match '169\.254\.169\.254'
} | Select-Object TimeCreated,
    @{N='Process';  E={$_.Properties[5].Value}},
    @{N='User';     E={$_.Properties[12].Value}},
    @{N='DestPort'; E={$_.Properties[22].Value}},
    @{N='DestIP';   E={$_.Properties[14].Value}} | Format-Table -AutoSize

Get-WinEvent -FilterHashtable @{
    LogName   = 'Microsoft-Windows-PowerShell/Operational'
    Id        = 4104
    StartTime = (Get-Date).AddHours(-24)
} | Where-Object {
    $_.Message -match '169\.254\.169\.254' -or
    $_.Message -match 'metadata/identity' -or
    $_.Message -match 'iam/security-credentials'
} | Select-Object TimeCreated,
    @{N='Script';E={$_.Properties[2].Value}} | Format-Table -AutoSize

# Hunt for temporary IMDS credentials used from non-cloud IP
aws cloudtrail lookup-events --lookup-attributes AttributeKey=EventName,AttributeValue=AssumeRole --max-items 100 | ConvertFrom-Json | Select-Object -ExpandProperty Events | Where-Object {
    $_.CloudTrailEvent | ConvertFrom-Json | ForEach-Object {
        $_.userIdentity.type -eq 'AssumedRole' -and $_.userAgent -notmatch 'aws-sdk'
    }
}
